insert into private.portal_navigation_node_v1 (node_id,parent_node_id,code,taxonomy,dimension,source_index_path,source_file,alias_codes,labels,label_strategy) values ('class:cpc:3.7.7.6','class:cpc:3.7.7','3897','cpc','classification','category[3]/category[7]/category[7]/category[6]','src/services/referenceResources/data/cpc/base.json','{}'::text[],'{"de":"Menschenhaar; Wolle oder andere Tierhaare oder andere textile Materialien; Perücken, falsche Bärte, Augenbrauen und Wimpern, Haarteile und dergleichen; Waren aus Menschenhaar a.n.g.; Rosshaar","en":"Human hair; wool or other animal hair or other textile materials; wigs, false beards, eyebrows and eyelashes, switches and the like; articles of human hair n.e.c.; horsehair","fr":"Cheveux humains; laine ou autres poils d''animaux ou autres matières textiles; perruques, fausses barbes, sourcils et cils, postiches et similaires; ouvrages en cheveux humains n.c.a.; crin","zh-CN":"人发；羊毛、其他动物毛或其他纺织材料；假发、假须、假眉、假睫、假发髻及类似品；其他未另列明的人发制品；马毛"}'::jsonb,'{"de":"project-reviewed-overlay","en":"official-source","fr":"project-reviewed-overlay","zh-CN":"project-reviewed-overlay"}'::jsonb);
