insert into private.portal_navigation_node_v1 (node_id,parent_node_id,code,taxonomy,dimension,source_index_path,source_file,alias_codes,labels,label_strategy) values ('class:cpc:3.7.7.6.1','class:cpc:3.7.7.6','38972','cpc','classification','category[3]/category[7]/category[7]/category[6]/category[1]','src/services/referenceResources/data/cpc/base.json','{}'::text[],'{"de":"Zugerichtetes, ausgedünntes, gebleichtes oder anderweitig bearbeitetes Menschenhaar; Wolle oder andere Tierhaare oder andere textile Materialien, für die Herstellung von Perücken oder dergleichen vorbereitet; Perücken, falsche Bärte, Augenbrauen und Wimpern, Haarteile und dergleichen aus Menschen- oder Tierhaar oder textilen Materialien; Waren aus Menschenhaar a.n.g.","en":"Human hair, dressed, thinned, bleached or otherwise worked; wool or other animal hair or other textile materials, prepared for use in making wigs or the like; wigs, false beards, eyebrows and eyelashes, switches and the like, of human or animal hair or of textile materials; articles of human hair n.e.c.","fr":"Cheveux humains apprêtés, amincis, blanchis ou autrement travaillés; laine ou autres poils d''animaux ou autres matières textiles, préparés pour la fabrication de perruques ou similaires; perruques, fausses barbes, sourcils et cils, postiches et similaires, en cheveux humains ou poils d''animaux ou en matières textiles; ouvrages en cheveux humains n.c.a.","zh-CN":"经梳理、稀薄处理、漂白或其他加工的人发；用于制作假发或类似品的羊毛、其他动物毛或其他纺织材料；人发、动物毛或纺织材料制成的假发、假须、假眉、假睫、假发髻及类似品；其他未另列明的人发制品"}'::jsonb,'{"de":"project-reviewed-overlay","en":"official-source","fr":"project-reviewed-overlay","zh-CN":"project-reviewed-overlay"}'::jsonb);
