insert into private.portal_navigation_node_v1 (node_id,parent_node_id,code,taxonomy,dimension,source_index_path,source_file,alias_codes,labels,label_strategy) values ('class:cpc:3.7.7.7.2','class:cpc:3.7.7.7','38993','cpc','classification','category[3]/category[7]/category[7]/category[7]/category[2]','src/services/referenceResources/data/cpc/base.json','{}'::text[],'{"de":"Besen, Bürsten, handbetriebene mechanische Bodenkehrer ohne Motor, Wischmopps und Staubwedel; vorbereitete Knoten und Büschel zur Besen- oder Bürstenherstellung; Farbauftragskissen und -rollen; Abzieher ausgenommen Rollenabzieher","en":"Brooms, brushes, hand-operated mechanical floor sweepers (not motorized), mops and feather dusters; prepared knots and tufts for broom or brush making; paint pads and rollers; squeegees (other than roller squeegees)","fr":"Balais, brosses, balayeuses mécaniques à main pour sols non motorisées, balais à franges et plumeaux; touffes et nœuds préparés pour la fabrication de balais ou brosses; tampons et rouleaux à peindre; raclettes, autres que les raclettes à rouleaux","zh-CN":"扫帚、刷子、手动机械扫地器（非电动）、拖把及羽毛掸子；制扫帚或刷子用的已制备束结和簇毛；涂漆垫和滚筒；刮水器（滚筒刮水器除外）"}'::jsonb,'{"de":"project-reviewed-overlay","en":"official-source","fr":"project-reviewed-overlay","zh-CN":"project-reviewed-overlay"}'::jsonb);
insert into private.portal_navigation_node_v1 (node_id,parent_node_id,code,taxonomy,dimension,source_index_path,source_file,alias_codes,labels,label_strategy) values ('class:cpc:3.7.7.7.3','class:cpc:3.7.7.7','38994','cpc','classification','category[3]/category[7]/category[7]/category[7]/category[3]','src/services/referenceResources/data/cpc/base.json','{}'::text[],'{"de":"Zigarettenanzünder und andere Anzünder; Tabakpfeifen sowie Zigarren- oder Zigarettenspitzen und Teile davon; Kämme, Haarspangen und dergleichen; Haarnadeln, Lockennadeln, Lockenklemmen, Lockenwickler und dergleichen ausgenommen elektrothermische Geräte sowie Teile davon; Parfümzerstäuber und ähnliche Toilettenzerstäuber sowie Fassungen und Köpfe dafür; Puderquasten und Kissen zum Auftragen von Kosmetika oder Toilettenpräparaten","en":"Cigarette lighters and other lighters; smoking pipes and cigar or cigarette holders, and parts thereof; combs, hair-slides and the like; hairpins, curling pins, curling grips, hair-curlers and the like (except electro-thermic apparatus), and parts thereof; scent sprays and similar toilet sprays, and mounts and heads therefor; powder-puffs and pads for the application of cosmetics or toilet preparations","fr":"Briquets à cigarettes et autres briquets; pipes et porte-cigares ou porte-cigarettes, et leurs parties; peignes, barrettes et similaires; épingles à cheveux, épingles à friser, pinces à friser, bigoudis et similaires, à l''exception des appareils électrothermiques, et leurs parties; vaporisateurs de parfums et vaporisateurs de toilette similaires, et leurs montures et têtes; houppettes et tampons pour l''application de produits cosmétiques ou de toilette","zh-CN":"香烟打火机和其他打火机；烟斗、雪茄或香烟烟嘴及其零件；梳子、发夹及类似品；发卡、卷发针、卷发夹、卷发器及类似品（电热器具除外）及其零件；香水喷雾器和类似化妆喷雾器及其底座和喷头；化妆品或盥洗用品用粉扑和粉垫"}'::jsonb,'{"de":"project-reviewed-overlay","en":"official-source","fr":"project-reviewed-overlay","zh-CN":"project-reviewed-overlay"}'::jsonb);
